import{_ as t,o,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"CDS Jewel -- RADOS QoS","description":"","frontmatter":{"title":"CDS Jewel -- RADOS QoS","date":"2015-08-03T00:00:00.000Z","updated":"2015-08-04T00:00:00.000Z","tags":["Ceph","Distributed Storage","QoS","RADOS","I/O Scheduler"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Jewel_--_RADOS_QoS.md","filePath":"posts/2015/CDS_Jewel_--_RADOS_QoS.md","lastUpdated":1780459816000}'),e={name:"posts/2015/CDS_Jewel_--_RADOS_QoS.md"};function s(n,l,S,a,g,p){return o(),i("div",null,[...l[0]||(l[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph分布式存储服务质量（QoS）策略讨论</p><p><strong>会议时间</strong>： 2023年11月</p><p><strong>参会人员</strong>： Ray、Clark、Sam、Josh等</p><p><strong>会议内容</strong>：</p><p><strong>一、QoS策略概述</strong></p><ul><li>会议讨论了Ceph分布式存储中的服务质量（QoS）策略，旨在为不同类型的存储请求提供差异化的服务质量。</li><li>当前Ceph的I/O调度器采用公平共享调度器，但需要进一步优化以支持QoS策略。</li></ul><p><strong>二、QoS策略实现方案</strong></p><ul><li><strong>基于EM算法的I/O调度器优化</strong>： <ul><li>引入EM算法，为客户端提供最小IOPS和最大IOPS的配置选项。</li><li>当客户端的IOPS请求超过最大限制时，系统将进行限制。</li><li>当最小IOPS得到保证时，超出部分将按照公平共享原则进行分配。</li></ul></li><li><strong>资源预留与容量控制</strong>： <ul><li>引入资源预留机制，以确保高优先级客户端的IOPS需求得到满足。</li><li>通过配置选项或管理工具设置资源预留策略。</li></ul></li><li><strong>性能自动检测</strong>： <ul><li>引入性能自动检测机制，实时评估存储集群的性能。</li><li>通过辅助工具或自研代码进行性能测试。</li></ul></li></ul><p><strong>三、相关讨论</strong></p><ul><li><strong>网络QoS</strong>： <ul><li>讨论了网络QoS对存储系统的影响，并探讨了如何将网络QoS与存储QoS相结合。</li></ul></li><li><strong>OSD性能自动检测</strong>： <ul><li>讨论了如何自动检测OSD的性能，并提出了基于OSD操作性能进行检测的方案。</li></ul></li><li><strong>客户端信任度</strong>： <ul><li>讨论了如何处理不信任的客户端，并提出了限制IOPS或拒绝QoS配置的方案。</li></ul></li></ul><p><strong>四、后续行动计划</strong></p><ul><li>Ray将继续开发基于EM算法的I/O调度器优化方案。</li><li>Sam将研究性能自动检测机制。</li><li>Clark将探讨网络QoS与存储QoS的结合方案。</li><li>全体成员将继续讨论客户端信任度问题。</li></ul><p><strong>五、关键术语</strong></p><ul><li><strong>QoS</strong>： 服务质量</li><li><strong>I/O调度器</strong>： Input/Output scheduler</li><li><strong>EM算法</strong>： Expectation-Maximization algorithm</li><li><strong>OSD</strong>： Object Storage Device</li><li><strong>PG</strong>： Placement Group</li><li><strong>RBD</strong>： RADOS Block Device</li></ul>',15)])])}const O=t(e,[["render",s]]);export{_ as __pageData,O as default};
